import { Component, input } from '@angular/core';

/** A grade's line of the summary: how many people are on it today, and their due-totals added up. */
export interface GradeSummary {
  grade: string;
  count: number;
  dueTotal: string;
}

/** A period's line of the summary: its due-total. */
export interface PeriodSummary {
  name: string;
  dueTotal: string;
}

/** A status's line of the summary: how many claims have it. */
export interface StatusSummary {
  status: string;
  count: number;
}

// The sheet in figures: per grade, the people on it today who are not retired and their due-totals;
// per period, its due-total; per status, how many claims have it. Each figure is the list's own.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-labelledby="summary-heading" data-testid="summary">
      <h2 id="summary-heading">Summary</h2>
      <table aria-label="Summary by grade">
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">People</th><th scope="col">Due</th></tr>
        </thead>
        <tbody>
          @for (g of grades(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table aria-label="Summary by period">
        <thead>
          <tr><th scope="col">Period</th><th scope="col">Due</th></tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ p.dueTotal }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table aria-label="Summary by status">
        <thead>
          <tr><th scope="col">Status</th><th scope="col">Claims</th></tr>
        </thead>
        <tbody>
          @for (s of statuses(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Summary {
  readonly grades = input.required<GradeSummary[]>();
  readonly periods = input.required<PeriodSummary[]>();
  readonly statuses = input.required<StatusSummary[]>();
}
import { Component, inject } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { Settings } from '../settings/settings';
import { SheetPicker } from '../session/sheet-picker';
import { SheetToday } from '../session/sheet-today';
import { SignIn } from '../session/sign-in';

// The one screen: sign in, then choose a sheet; everything else is kept per sheet.
@Component({
  selector: 'app-home',
  imports: [SignIn, SheetPicker, SheetToday, Settings, People],
  template: `
    @if (session.user(); as user) {
      <header>
        Signed in as <strong data-testid="current-user">{{ user }}</strong>
      </header>
      <app-sheet-picker />
      <app-sheet-today />
      @if (session.sheet()) {
        <app-settings />
      }
      <app-people />
      @if (!session.sheet()) {
        <p data-testid="home-empty">Load a sheet to begin.</p>
      }
    } @else {
      <app-sign-in />
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
}
import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}

